620:   if (!REMEMBER_ACTIONS.includes(action)) {
621:     throw new Error(
622:       `Invalid remember action ${JSON.stringify(request.action)}: expected 'remember', 'correct', 'supersede' or 'retract'.`,
623:     );
624:   }
625:   if (request.role !== undefined && !REMEMBER_ROLES.includes(request.role)) {
626:     throw new Error(
627:       `Invalid remember role ${JSON.stringify(request.role)}.`,
628:     );
629:   }
630:   if (
631:     request.caller_scope !== undefined &&
632:     !request.caller_scope.trim()
633:   ) {
634:     throw new Error("remember caller_scope must be a non-empty string.");
635:   }
636:   if (
637:     request.evidence_refs !== undefined &&
638:     !Array.isArray(request.evidence_refs)
639:   ) {
640:     throw new Error("remember evidence_refs must be a list.");
641:   }
