670: function validateTraceRequest(request: TraceRequest): void {
671:   if (request.mode === "get" || request.mode === "verify") {
672:     if (!request.trace_id.trim()) {
673:       throw new Error(`Trace mode '${request.mode}' requires trace_id.`);
674:     }
675:   } else if (request.mode === "find") {
676:     const filters = request.filters ?? {};
677:     if (
678:       filters.limit !== undefined &&
679:       (!Number.isInteger(filters.limit) || filters.limit < 1)
680:     ) {
681:       throw new Error("Trace find limit must be a positive integer.");
682:     }
683:   } else if (request.mode === "explain") {
684:     if (!request.trace_id.trim() || !request.candidate_id.trim()) {
685:       throw new Error(
686:         "Trace mode 'explain' requires trace_id and candidate_id.",
687:       );
688:     }
689:   } else if (request.mode === "replay") {
690:     if (!request.trace_id.trim()) {
691:       throw new Error("Trace mode 'replay' requires trace_id.");
692:     }
693:     if (request.replay_kind !== "trust" && request.replay_kind !== "selection") {
694:       throw new Error(
695:         `Invalid replay_kind ${JSON.stringify(request.replay_kind)}.`,
696:       );
697:     }
698:   } else if (request.mode === "diff") {
699:     if (!request.trace_id.trim() || !request.diff_with.trim()) {
700:       throw new Error(
701:         "Trace mode 'diff' requires trace_id and diff_with.",
702:       );
703:     }
704:   }
705: }
