import { Pool } from "pg";

import { connectPool, ensureExtension } from "./db";
import { canonicalProjectDir, doctorBaseline } from "./doctor";
import { buildEmbedder, type EmbeddingProvider, type EmbeddingSpec } from "./embeddings";
import { assertSchemaName, EngineError } from "./errors";
import { chunkSource, discover, parseFile, type ChunkingConfig, DEFAULT_CHUNKING } from "./ingest";
import { Retriever, type RetrievalConfig, type RetrievalTrace } from "./retrieval";
import { BaselineStore, ident, readProjectMeta } from "./storage";

export type EngineOptions = {
  dsn: string;
  schema: string;
  projectDirectory: string;
  embedding: EmbeddingSpec;
  retrieval: RetrievalConfig;
  chunking?: ChunkingConfig;
};

export type RefreshReport = {
  ok: boolean;
  schema: string;
  discovered: number;
  indexed: number;
  unchanged: number;
  added: number;
  changed: number;
  removed: number;
  chunks: number;
  embedded: number;
  failed: string[];
  message?: string;
};

export type SearchItem = {
  chunk_id: string;
  source_id: string;
  section: string | null;
  rank: number;
  score: number;
  text: string;
  lexical_rank: number | null;
  dense_rank: number | null;
  stage: string;
};

export type SearchResult = {
  ok: boolean;
  indexed: boolean;
  schema: string;
  items: SearchItem[];
  trace: {
    query: string;
    mode: string;
    lexical_count: number;
    dense_count: number;
    fused_count: number;
    reranked_count: number;
    lexical_ids: string[];
    dense_ids: string[];
    fused_ids: string[];
    reranked_ids: string[];
    latencies_ms: Record<string, number>;
    embedding: { provider: string; model: string; dimension: number; version: string };
    retrieval: {
      mode: string;
      lexical_k: number;
      dense_k: number;
      fusion_k: number;
      rerank_k: number;
      reranker: string;
    };
    dense_executed: boolean;
  } | null;
  message?: string;
};

export const NOT_INDEXED_MESSAGE =
  "This project's remembering schema has not been indexed yet. Run memory_setup to initialise the schema and ingest the repository.";

/**
 * Native TypeScript baseline engine (Stage 2 vertical slice).
 * Owns its pg Pool; call close() when done.
 */
export class RememberingEngine {
  private pool: Pool | null = null;
  private embedder: EmbeddingProvider;
  readonly chunking: ChunkingConfig;

  constructor(private readonly options: EngineOptions) {
    assertSchemaName(options.schema);
    this.embedder = buildEmbedder(options.embedding);
    this.chunking = options.chunking ?? DEFAULT_CHUNKING;
  }

  /** Override the embedder (tests / differential harness). */
  withEmbedder(embedder: EmbeddingProvider): this {
    this.embedder = embedder;
    return this;
  }

  private async poolConnected(): Promise<Pool> {
    if (!this.pool) this.pool = await connectPool(this.options.dsn);
    return this.pool;
  }

  async close(): Promise<void> {
    if (this.pool) {
      await this.pool.end().catch(() => {});
      this.pool = null;
    }
  }

  private store(pool: Pool): BaselineStore {
    return new BaselineStore(pool, this.options.dsn, this.options.schema);
  }

  async doctor(): Promise<Record<string, unknown>> {
    const pool = await this.poolConnected();
    const baseline = await doctorBaseline(pool, {
      dsn: this.options.dsn,
      schema: this.options.schema,
      projectDirectory: this.options.projectDirectory,
      embedding: this.options.embedding,
    });
    return { ...baseline, native: true };
  }

  async setup(): Promise<{ ok: boolean; schema: string; embedding: { provider: string; model: string; dimension: number; version: string } }> {
    const pool = await this.poolConnected();
    const client = await pool.connect();
    try {
      await ensureExtension(client, "vector");
      await ensureExtension(client, "pg_trgm");
    } finally {
      client.release();
    }
    const probe = await this.embedder.embed(["dimension probe"]);
    const dimension = probe.dimension;
    const store = this.store(pool);
    await store.initialise(dimension);
    await this.ensureProjectMeta(pool);
    await store.ensureHnsw();
    return {
      ok: true,
      schema: this.options.schema,
      embedding: {
        provider: probe.provider,
        model: probe.model,
        dimension: probe.dimension,
        version: `${probe.provider}:${probe.model}:${probe.dimension}`,
      },
    };
  }

  private async ensureProjectMeta(pool: Pool): Promise<void> {
    const canonical = await canonicalProjectDir(this.options.projectDirectory);
    const client = await pool.connect();
    try {
      const meta = await readProjectMeta(client, this.options.schema);
      const recorded = meta["project.path"];
      if (recorded != null && recorded !== canonical) {
        throw new EngineError(
          "SCHEMA_MISMATCH",
          `schema ${JSON.stringify(this.options.schema)} is already claimed by project ${JSON.stringify(recorded)}, but this project resolves to ${JSON.stringify(canonical)}. Refusing to mix projects: fix the schema configuration instead of sharing an index.`,
        );
      }
      const stamp = new Date().toISOString();
      const s = ident(this.options.schema);
      for (const [key, value] of [
        ["project.path", canonical],
        ["project.schema", this.options.schema],
        ["project.recorded_at", stamp],
      ] as Array<[string, string]>) {
        await client.query(
          `INSERT INTO ${s}.meta (key, value) VALUES ($1, $2) ON CONFLICT (key) DO NOTHING`,
          [key, value],
        );
      }
    } finally {
      client.release();
    }
  }

  async refresh(): Promise<RefreshReport> {
    const pool = await this.poolConnected();
    const store = this.store(pool);
    // Baseline refresh requires an initialised store (mirrors bridge initialise()).
    const probe = await this.embedder.embed(["dimension probe"]);
    await store.initialise(probe.dimension);
    await this.ensureProjectMeta(pool);

    const report: RefreshReport = {
      ok: true,
      schema: this.options.schema,
      discovered: 0,
      indexed: 0,
      unchanged: 0,
      added: 0,
      changed: 0,
      removed: 0,
      chunks: 0,
      embedded: 0,
      failed: [],
    };
    const { realpath } = await import("node:fs/promises");
    let root: string;
    try {
      root = await realpath(this.options.projectDirectory);
    } catch {
      const { resolve } = await import("node:path");
      root = resolve(this.options.projectDirectory);
    }
    const paths = await discover(root);
    report.discovered = paths.length;
    const known = await store.knownSources();
    const seen = new Set<string>();
    const version = await this.embeddingVersion();
    for (const fullPath of paths) {
      const source = await parseFile(fullPath, root);
      if (!source) {
        const { basename } = await import("node:path");
        report.failed.push(basename(fullPath));
        continue;
      }
      seen.add(source.sourceId);
      if (known[source.sourceId] === source.contentHash) {
        report.unchanged += 1;
        continue;
      }
      const isNew = !(source.sourceId in known);
      await store.upsertSource(source.sourceId, source.artifactType, source.contentHash, source.timestamp);
      const chunks = chunkSource(source, this.chunking);
      const texts = chunks.map((c) => c.text);
      const vectors = texts.length ? (await this.embedder.embed(texts)).vectors : [];
      const rows = chunks.map((c, i) => ({
        chunkId: c.chunkId,
        sourceId: c.sourceId,
        ordinal: c.ordinal,
        text: c.text,
        section: c.section,
        charStart: c.charStart,
        charEnd: c.charEnd,
        contentHash: c.contentHash,
        chunker: `${this.chunking.policy}:${this.chunking.chunkerVersion}`,
        embeddingVersion: version,
        embedding: vectors[i] ?? [],
      }));
      await store.replaceChunks(source.sourceId, rows);
      report.chunks += rows.length;
      report.embedded += rows.length;
      report.indexed += 1;
      if (isNew) report.added += 1;
      else report.changed += 1;
    }
    for (const sourceId of Object.keys(known).sort()) {
      if (seen.has(sourceId)) continue;
      // Explicit-memory sources are managed by the write subsystem,
      // not by repository discovery: refresh must never prune them.
      if (sourceId.startsWith("memory://")) continue;
      await store.removeSource(sourceId);
      report.removed += 1;
    }
    await store.ensureHnsw();
    await this.verify(store);
    return report;
  }

  private async embeddingVersion(): Promise<string> {
    // Version without dimension probe side effects: derive from spec.
    // The stored per-chunk version is provider:model:dimension after first embed.
    const probe = await this.embedder.embed(["dimension probe"]);
    return `${probe.provider}:${probe.model}:${probe.dimension}`;
  }

  async verify(): Promise<void> {
    const pool = await this.poolConnected();
    await this.verifyWith(this.store(pool));
  }

  private async verifyWith(store: BaselineStore): Promise<void> {
    if (await store.orphanChunks()) {
      throw new EngineError("VERIFY_FAILED", "orphan chunks remain after refresh");
    }
    const versions = await store.embeddingVersions();
    if (versions.length > 1) {
      throw new EngineError(
        "VERIFY_FAILED",
        `mixed embedding versions in store: ${JSON.stringify(versions.sort())}`,
      );
    }
  }

  async search(query: string, limit = 8): Promise<SearchResult> {
    const trimmed = query.trim();
    if (!trimmed) {
      return { ok: true, indexed: true, schema: this.options.schema, items: [], trace: null, message: "empty query: no retrieval attempted." };
    }
    const boundedLimit = Math.max(1, Math.min(limit, 20));
    const pool = await this.poolConnected();
    const client = await pool.connect();
    try {
      const reg = await client.query("SELECT to_regclass($1)", [`${this.options.schema}.chunks`]);
      if (reg.rows[0]?.to_regclass == null) {
        return { ok: true, indexed: false, schema: this.options.schema, items: [], trace: null, message: NOT_INDEXED_MESSAGE };
      }
    } finally {
      client.release();
    }
    const probe = await this.embedder.embed(["dimension probe"]);
    const embIdentity = {
      provider: probe.provider,
      model: probe.model,
      dimension: probe.dimension,
      version: `${probe.provider}:${probe.model}:${probe.dimension}`,
    };
    const retriever = new Retriever(this.store(pool), this.embedder, this.options.retrieval);
    const trace: RetrievalTrace = await retriever.retrieve(trimmed);
    const lexicalRanks = new Map(trace.lexical.map((c) => [c.chunkId, c.rank]));
    const denseRanks = new Map(trace.dense.map((c) => [c.chunkId, c.rank]));
    const finalStage = this.options.retrieval.reranker !== "none" ? "reranked" : "fused";
    const items: SearchItem[] = trace.reranked.slice(0, boundedLimit).map((c) => ({
      chunk_id: c.chunkId,
      source_id: c.sourceId,
      section: c.section,
      rank: c.rank,
      score: c.score,
      text: c.text,
      lexical_rank: lexicalRanks.get(c.chunkId) ?? null,
      dense_rank: denseRanks.get(c.chunkId) ?? null,
      stage: finalStage,
    }));
    return {
      ok: true,
      indexed: true,
      schema: this.options.schema,
      items,
      trace: {
        query: trace.query,
        mode: this.options.retrieval.mode,
        lexical_count: trace.lexical.length,
        dense_count: trace.dense.length,
        fused_count: trace.fused.length,
        reranked_count: trace.reranked.length,
        lexical_ids: trace.lexical.map((c) => c.chunkId),
        dense_ids: trace.dense.map((c) => c.chunkId),
        fused_ids: trace.fused.map((c) => c.chunkId),
        reranked_ids: trace.reranked.map((c) => c.chunkId),
        latencies_ms: Object.fromEntries(
          Object.entries(trace.latenciesMs).map(([k, v]) => [k, Math.round(v * 100) / 100]),
        ),
        embedding: embIdentity,
        retrieval: {
          mode: this.options.retrieval.mode,
          lexical_k: this.options.retrieval.lexicalK,
          dense_k: this.options.retrieval.denseK,
          fusion_k: this.options.retrieval.fusionK,
          rerank_k: this.options.retrieval.rerankK,
          reranker: this.options.retrieval.reranker,
        },
        dense_executed: "dense" in trace.latenciesMs,
      },
    };
  }
}

import { describe, expect, test } from "bun:test";

import { HashingEmbedder } from "./embeddings";
import { overlapRerank, reciprocalRankFusion, Retriever } from "./retrieval";
import type { ScoredChunk } from "./storage";

process.env.REMEMBERING_ALLOW_TEST_EMBEDDINGS = "1";

function chunk(id: string, rank: number, score = 1): ScoredChunk {
  return { chunkId: id, sourceId: `src-${id}`, text: `text ${id}`, section: null, score, rank };
}

describe("reciprocal_rank_fusion parity (baseline/retrieval.py)", () => {
  test("single ranking preserves order with RRF scores", () => {
    const fused = reciprocalRankFusion([[chunk("b", 1), chunk("a", 2)]], 60);
    expect(fused.map((c) => c.chunkId)).toEqual(["b", "a"]);
    expect(fused[0]?.score).toBeCloseTo(1 / 61, 9);
    expect(fused.map((c) => c.rank)).toEqual([1, 2]);
  });

  test("shared hits outrank single-list hits; ties break by chunk_id", () => {
    const lexical = [chunk("a", 1), chunk("b", 2)];
    const dense = [chunk("b", 1), chunk("c", 2)];
    const fused = reciprocalRankFusion([lexical, dense], 60);
    expect(fused.map((c) => c.chunkId)).toEqual(["b", "a", "c"]);
  });

  test("fusion k changes absolute scores but not this ordering", () => {
    const lexical = [chunk("a", 1)];
    const dense = [chunk("a", 1)];
    const small = reciprocalRankFusion([lexical, dense], 1);
    const large = reciprocalRankFusion([lexical, dense], 60);
    expect(small[0]?.score).toBeGreaterThan(large[0]?.score ?? 0);
  });
});

describe("overlap reranker parity", () => {
  test("orders by token overlap then chunk_id", () => {
    const chunks = [chunk("c2", 1), chunk("c1", 2), chunk("c3", 3)];
    chunks[0]!.text = "unrelated words here";
    chunks[1]!.text = "authentication design changed";
    chunks[2]!.text = "authentication design changed twice";
    const ranked = overlapRerank("authentication design", chunks, 3);
    expect(ranked.map((c) => c.chunkId)).toEqual(["c1", "c3", "c2"]);
    expect(ranked[0]?.rank).toBe(1);
  });

  test("respects k", () => {
    const chunks = [chunk("a", 1), chunk("b", 2)];
    expect(overlapRerank("a b", chunks, 1)).toHaveLength(1);
  });
});

describe("Retriever stage semantics", () => {
  test("lexical mode never calls the embedder", async () => {
    let calls = 0;
    const store = {
      lexicalSearch: async () => [chunk("a", 1)],
      denseSearch: async () => { throw new Error("must not run"); },
    };
    const embedder = new HashingEmbedder(8);
    const counting = {
      name: "hashing",
      version: () => "hashing:8",
      embed: async (texts: string[]) => { calls += 1; return embedder.embed(texts); },
    };
    const retriever = new Retriever(store, counting, {
      mode: "lexical", lexicalK: 5, denseK: 5, fusionK: 60, rerankK: 5, reranker: "none",
    });
    const trace = await retriever.retrieve("hello");
    expect(trace.lexical.map((c) => c.chunkId)).toEqual(["a"]);
    expect(trace.dense).toEqual([]);
    expect(trace.fused.map((c) => c.chunkId)).toEqual(["a"]);
    expect(calls).toBe(0);
    expect(trace.latenciesMs["dense"]).toBeUndefined();
  });

  test("hybrid fuses both stages and records latencies", async () => {
    const store = {
      lexicalSearch: async () => [chunk("a", 1), chunk("b", 2)],
      denseSearch: async () => [chunk("b", 1), chunk("c", 2)],
    };
    const retriever = new Retriever(store, new HashingEmbedder(8), {
      mode: "hybrid", lexicalK: 5, denseK: 5, fusionK: 60, rerankK: 5, reranker: "none",
    });
    const trace = await retriever.retrieve("query");
    expect(trace.fused.map((c) => c.chunkId)).toEqual(["b", "a", "c"]);
    expect(trace.reranked.map((c) => c.chunkId)).toEqual(["b", "a", "c"]);
    expect(trace.latenciesMs["lexical"]).toBeDefined();
    expect(trace.latenciesMs["dense"]).toBeDefined();
  });

  test("cross-encoder reranker is refused by the TS engine", () => {
    const store = { lexicalSearch: async () => [], denseSearch: async () => [] };
    expect(
      () => new Retriever(store, new HashingEmbedder(8), {
        mode: "hybrid", lexicalK: 5, denseK: 5, fusionK: 60, rerankK: 5, reranker: "cross-encoder",
      }),
    ).toThrow(/cross-encoder/);
  });
});

#!/usr/bin/env bun
/**
 * Native-engine dev CLI (Stage 2). Same config surface as dev-cli.ts
 * but executes the TypeScript engine directly — no Python, no bridge:
 *
 *   bun src/native-cli.ts doctor [--dir <path>]
 *   bun src/native-cli.ts setup [--dir <path>]
 *   bun src/native-cli.ts refresh [--dir <path>]
 *   bun src/native-cli.ts search "query" [--dir <path>] [--limit N]
 *
 * Used for differential parity debugging against the Python bridge.
 */

import { loadConfig } from "./config";
import { RememberingEngine } from "./engine/pipeline";

function usage(): never {
  console.error("usage: native-cli.ts <doctor|setup|refresh|search> [query] [--dir <path>] [--limit N]");
  process.exit(2);
}

const rawArgs = process.argv.slice(2);
const command = rawArgs[0];
if (!command) usage();

let directory = process.cwd();
const dirFlag = rawArgs.indexOf("--dir");
if (dirFlag !== -1) {
  directory = rawArgs[dirFlag + 1] ?? directory;
  rawArgs.splice(dirFlag, 2);
}
function flagValue(name: string): string | undefined {
  const flag = rawArgs.indexOf(name);
  if (flag === -1) return undefined;
  const value = rawArgs[flag + 1];
  rawArgs.splice(flag, 2);
  return value;
}
const limitFlag = flagValue("--limit");
const limit = limitFlag !== undefined ? Number(limitFlag) : 8;
const rest = rawArgs.slice(1);

const config = await loadConfig(directory);
const engine = new RememberingEngine({
  dsn: config.dsn,
  schema: config.schema,
  projectDirectory: directory,
  embedding: {
    provider: config.embedding.provider as "ollama" | "sentence-transformers" | "hashing",
    model: config.embedding.model,
    host: config.embedding.host,
  },
  retrieval: {
    mode: config.retrieval.mode,
    lexicalK: config.retrieval.lexicalK,
    denseK: config.retrieval.denseK,
    fusionK: config.retrieval.fusionK,
    rerankK: config.retrieval.rerankK,
    reranker: config.retrieval.reranker,
  },
});

let result: unknown;
try {
  switch (command) {
    case "doctor":
      result = await engine.doctor();
      break;
    case "setup":
      result = await engine.setup();
      break;
    case "refresh":
      result = await engine.refresh();
      break;
    case "search":
      result = await engine.search(rest.join(" ") || "test", limit);
      break;
    default:
      usage();
  }
} finally {
  await engine.close();
}

console.log(JSON.stringify(result, null, 2));
if (typeof result === "object" && result !== null && "ok" in result && (result as { ok: unknown }).ok === false) {
  process.exitCode = 1;
}

