618: function validateRememberRequest(request: RememberRequest): void {
619:   const action = request.action ?? "remember";
620:   if (!REMEMBER_ACTIONS.includes(action)) {
621:     throw new Error(
622:       `Invalid remember action ${JSON.stringify(request.action)}: expected 'remember', 'correct', 'supersede' or 'retract'.`,
623:     );
624:   }
625:   if (request.role !== undefined && !REMEMBER_ROLES.includes(request.role)) {
626:     throw new Error(
627:       `Invalid remember role ${JSON.stringify(request.role)}.`,
628:     );
629:   }
630:   if (
631:     request.caller_scope !== undefined &&
632:     !request.caller_scope.trim()
633:   ) {
634:     throw new Error("remember caller_scope must be a non-empty string.");
635:   }
636:   if (
637:     request.evidence_refs !== undefined &&
638:     !Array.isArray(request.evidence_refs)
639:   ) {
640:     throw new Error("remember evidence_refs must be a list.");
641:   }
642: }
643: 
644: const LOOP_ACTIONS: LoopAction[] = ["list", "get", "history"];
645: const LOOP_STATES: LoopState[] = ["open", "completed", "cancelled", "superseded", "uncertain"];
646: 
647: function validateLoopRequest(request: LoopRequest): void {
648:   const action = request.action ?? "list";
649:   if (!LOOP_ACTIONS.includes(action)) {
650:     throw new Error(
651:       `Invalid loops action ${JSON.stringify(request.action)}: expected 'list', 'get' or 'history'.`,
652:     );
653:   }
654:   if ((action === "get" || action === "history") && !request.loop_id?.trim()) {
655:     throw new Error(`Loops action '${action}' requires loop_id.`);
656:   }
657:   if (request.state !== undefined && !LOOP_STATES.includes(request.state)) {
658:     throw new Error(
659:       `Invalid loop state ${JSON.stringify(request.state)}.`,
660:     );
661:   }
662:   if (
663:     request.limit !== undefined &&
664:     (!Number.isInteger(request.limit) || request.limit < 1)
665:   ) {
666:     throw new Error("Loops limit must be a positive integer.");
667:   }
668: }
669: 
670: function validateTraceRequest(request: TraceRequest): void {
671:   if (request.mode === "get" || request.mode === "verify") {
672:     if (!request.trace_id.trim()) {
673:       throw new Error(`Trace mode '${request.mode}' requires trace_id.`);
674:     }
675:   } else if (request.mode === "find") {
676:     const filters = request.filters ?? {};
677:     if (
678:       filters.limit !== undefined &&
679:       (!Number.isInteger(filters.limit) || filters.limit < 1)
680:     ) {
681:       throw new Error("Trace find limit must be a positive integer.");
682:     }
683:   } else if (request.mode === "explain") {
684:     if (!request.trace_id.trim() || !request.candidate_id.trim()) {
685:       throw new Error(
686:         "Trace mode 'explain' requires trace_id and candidate_id.",
687:       );
688:     }
689:   } else if (request.mode === "replay") {
690:     if (!request.trace_id.trim()) {
691:       throw new Error("Trace mode 'replay' requires trace_id.");
692:     }
693:     if (request.replay_kind !== "trust" && request.replay_kind !== "selection") {
694:       throw new Error(
695:         `Invalid replay_kind ${JSON.stringify(request.replay_kind)}.`,
696:       );
697:     }
698:   } else if (request.mode === "diff") {
699:     if (!request.trace_id.trim() || !request.diff_with.trim()) {
700:       throw new Error(
701:         "Trace mode 'diff' requires trace_id and diff_with.",
702:       );
703:     }
704:   }
705: }
706: 
707: function validateWorkRequest(work: WorkRequest): void {
708:   const mode = work.mode ?? "auto";
709:   if (mode !== "auto" && mode !== "explicit" && mode !== "none") {
710:     throw new Error(
711:       `Invalid work mode ${JSON.stringify(work.mode)}: expected 'auto', 'explicit' or 'none'.`,
712:     );
713:   }
714:   if (mode === "explicit" && !work.work_type?.trim()) {
715:     throw new Error("Explicit work requires work_type.");
716:   }
717:   if (work.signals !== undefined && !Array.isArray(work.signals)) {
718:     throw new Error("work.signals must be a list.");
719:   }
720: }
721: 
722: function validateTemporalRequest(temporal: TemporalStandpointRequest): void {
723:   const mode = temporal.mode ?? "current";
724:   if (mode !== "current" && mode !== "valid_at" && mode !== "as_known" && mode !== "bitemporal") {
725:     throw new Error(
726:       `Invalid temporal mode ${JSON.stringify(temporal.mode)}: expected 'current', 'valid_at', 'as_known' or 'bitemporal'.`,
727:     );
728:   }
729:   if ((mode === "valid_at" || mode === "bitemporal") && !temporal.valid_at?.trim()) {
730:     throw new Error(`Temporal mode '${mode}' requires valid_at.`);
731:   }
732:   if ((mode === "as_known" || mode === "bitemporal") && !temporal.known_at?.trim()) {
733:     throw new Error(`Temporal mode '${mode}' requires known_at.`);
734:   }
735: }
