import { EngineError } from "../../errors";
import {
  memorySourceId,
  newActionId,
  newRecordId,
  validateWriteInput,
  type MemoryActionRecord,
  type MemoryRecord,
  type RememberAction,
  type RememberRole,
} from "./model";
import { authorizeWrite, type WritePolicy } from "./policy";
import type { WriteStore } from "./store";

export type WriteInput = {
  action?: RememberAction;
  content?: string;
  targetRecordId?: string;
  role?: RememberRole;
  reason?: string;
  evidenceRefs?: string[];
  callerScope?: string;
  origin?: "opencode" | "cli";
  eventTime?: string;
  effectiveFrom?: string;
  idempotencyKey?: string;
};

export type WriteOutput = {
  ok: boolean;
  code?: string;
  reason?: string;
  actionId?: string;
  action?: string;
  recordId?: string | null;
  targetRecordId?: string | null;
  duplicate?: boolean;
  authorization?: {
    verdict: string;
    reason: string;
    policyVersion: string;
    policyDigest: string;
    matchedGrantId: string | null;
  };
  record?: { role: string; standingCeiling: string; sourceId: string; lineageRoot: string } | null;
  relation?: { type: string; targetRecordId: string } | null;
};

/** Explicit attributed writes over an append-only record/action history. */
export class WriteService {
  constructor(
    private readonly store: WriteStore,
    private readonly policy: WritePolicy,
    private readonly now: () => string = () => new Date().toISOString(),
    /** Index hook wires explicit records into retrieval (engine supplies PG indexing). */
    private readonly indexRecord?: (record: MemoryRecord) => Promise<void>,
  ) {}

  async execute(input: WriteInput): Promise<WriteOutput> {
    const action = input.action ?? "remember";
    const role = input.role ?? "ordinary";
    const callerScope = input.callerScope ?? "default";
    const origin = input.origin ?? "opencode";
    validateWriteInput({
      action, content: input.content, target_record_id: input.targetRecordId,
      role, reason: input.reason, evidence_refs: input.evidenceRefs, caller_scope: callerScope,
    });
    if (input.idempotencyKey) {
      const prior = await this.store.getActionByIdempotency(input.idempotencyKey);
      if (prior) {
        const record = prior.recordId ? await this.store.getRecord(prior.recordId) : null;
        return {
          ok: true, actionId: prior.actionId, action: prior.action,
          recordId: prior.recordId, targetRecordId: prior.targetRecordId, duplicate: true,
          record: record ? { role: record.role, standingCeiling: record.standingCeiling, sourceId: record.sourceId, lineageRoot: record.lineageRoot } : null,
          relation: prior.relation,
        };
      }
    }
    const auth = authorizeWrite(this.policy, { role, evidenceRefs: input.evidenceRefs ?? [], callerScope, origin });
    if (auth.verdict === "deny") {
      return {
        ok: false, code: "MEMORY_WRITE_DENIED", reason: auth.reason,
        authorization: { verdict: auth.verdict, reason: auth.reason, policyVersion: auth.policyVersion, policyDigest: auth.policyDigest, matchedGrantId: auth.matchedGrantId },
      };
    }
    const createdAt = this.now();
    const eventTime = input.eventTime ?? createdAt;
    const effectiveFrom = input.effectiveFrom ?? eventTime;

    if (action === "remember") {
      const recordId = newRecordId();
      const record: MemoryRecord = {
        recordId, content: (input.content as string).trim(), role,
        sourceId: memorySourceId(recordId), lineageRoot: recordId,
        standingCeiling: role === "production_state" ? "S3" : "FULL",
        state: "active", callerScope, origin,
        evidenceRefs: input.evidenceRefs ?? [],
        eventTime, effectiveFrom, createdAt,
      };
      await this.store.putRecord(record);
      const actionRecord: MemoryActionRecord = {
        actionId: newActionId(), action, recordId, targetRecordId: null,
        reason: input.reason ?? "", callerScope, origin,
        idempotencyKey: input.idempotencyKey ?? null, relation: null, createdAt,
      };
      await this.store.putAction(actionRecord);
      if (this.indexRecord) await this.indexRecord(record);
      return {
        ok: true, actionId: actionRecord.actionId, action, recordId, targetRecordId: null,
        authorization: authz(auth),
        record: { role: record.role, standingCeiling: record.standingCeiling, sourceId: record.sourceId, lineageRoot: record.lineageRoot },
        relation: null,
      };
    }

    const targetId = input.targetRecordId as string;
    const target = await this.store.getRecord(targetId);
    if (!target) {
      return { ok: false, code: "MEMORY_TARGET_NOT_FOUND", reason: `no memory record ${JSON.stringify(targetId)}.`, authorization: authz(auth) };
    }
    if (action === "retract") {
      if (target.state === "retracted") {
        return { ok: false, code: "MEMORY_WRITE_DENIED", reason: "record is already retracted.", authorization: authz(auth) };
      }
      await this.store.updateRecordState(targetId, "retracted");
      const actionRecord: MemoryActionRecord = {
        actionId: newActionId(), action, recordId: null, targetRecordId: targetId,
        reason: input.reason ?? "", callerScope, origin,
        idempotencyKey: input.idempotencyKey ?? null,
        relation: { type: "retracts", targetRecordId: targetId }, createdAt,
      };
      await this.store.putAction(actionRecord);
      return {
        ok: true, actionId: actionRecord.actionId, action, recordId: null, targetRecordId: targetId,
        authorization: authz(auth), record: null,
        relation: { type: "retracts", targetRecordId: targetId },
      };
    }

    // correct | supersede: new record preserves lineage; original stays in history.
    if (target.state === "retracted") {
      return { ok: false, code: "MEMORY_WRITE_DENIED", reason: "cannot correct a retracted record; remember anew instead.", authorization: authz(auth) };
    }
    if (!input.content?.trim()) {
      throw new EngineError("MEMORY_WRITE_DENIED", `action '${action}' requires non-empty content.`);
    }
    const recordId = newRecordId();
    const record: MemoryRecord = {
      recordId, content: (input.content as string).trim(), role,
      sourceId: memorySourceId(recordId), lineageRoot: target.lineageRoot,
      standingCeiling: target.standingCeiling, state: "active",
      callerScope, origin, evidenceRefs: input.evidenceRefs ?? [],
      eventTime, effectiveFrom, createdAt,
    };
    await this.store.putRecord(record);
    await this.store.updateRecordState(targetId, action === "correct" ? "corrected" : "superseded");
    const actionRecord: MemoryActionRecord = {
      actionId: newActionId(), action, recordId, targetRecordId: targetId,
      reason: input.reason ?? "", callerScope, origin,
      idempotencyKey: input.idempotencyKey ?? null,
      relation: { type: action === "correct" ? "corrects" : "supersedes", targetRecordId: targetId },
      createdAt,
    };
    await this.store.putAction(actionRecord);
    if (this.indexRecord) await this.indexRecord(record);
    return {
      ok: true, actionId: actionRecord.actionId, action, recordId, targetRecordId: targetId,
      authorization: authz(auth),
      record: { role: record.role, standingCeiling: record.standingCeiling, sourceId: record.sourceId, lineageRoot: record.lineageRoot },
      relation: { type: action === "correct" ? "corrects" : "supersedes", targetRecordId: targetId },
    };
  }
}

function authz(auth: { verdict: string; reason: string; policyVersion: string; policyDigest: string; matchedGrantId: string | null }) {
  return { verdict: auth.verdict, reason: auth.reason, policyVersion: auth.policyVersion, policyDigest: auth.policyDigest, matchedGrantId: auth.matchedGrantId };
}

import type { FrameResult } from "./frame/model";
import { selectCandidates, type Budget, type SelectionCandidate, type SelectionMode } from "./selection/service";
import { screenInstructions, type StandingState, type TrustLevel, type TrustPolicy } from "./trust/model";
import { decideTrust } from "./trust/standing";
import type { TemporalStandpoint } from "./temporal/model";

export type MemoryRoute = "recall" | "influence";
export type RouteRequest = "auto" | MemoryRoute;

export type RouteBlock = {
  route: MemoryRoute;
  routeSource: "explicit" | "deterministic";
  routeReason: string;
  routeAmbiguous: boolean;
};

const INFLUENCE_CUES = /\b(should|must|do|implement|fix|change|update|deploy|run|execute|decide|choose|recommend|proceed|apply)\b/i;
const RECALL_CUES = /\b(what|why|when|where|who|history|decided|was|were|previously|before|recorded|happened)\b/i;

/** Deterministic route resolution. Auto never hides ambiguity. */
export function resolveRoute(query: string, requested: RouteRequest = "auto"): RouteBlock {
  if (requested === "recall" || requested === "influence") {
    return {
      route: requested,
      routeSource: "explicit",
      routeReason: `caller requested '${requested}'.`,
      routeAmbiguous: false,
    };
  }
  const influence = INFLUENCE_CUES.test(query);
  const recall = RECALL_CUES.test(query);
  if (influence && !recall) {
    return { route: "influence", routeSource: "deterministic", routeReason: "query carries present-action cues.", routeAmbiguous: false };
  }
  if (recall && !influence) {
    return { route: "recall", routeSource: "deterministic", routeReason: "query carries historical-recall cues.", routeAmbiguous: false };
  }
  return {
    route: "recall",
    routeSource: "deterministic",
    routeReason: influence && recall
      ? "query carries both recall and influence cues; defaulting to recall and reporting ambiguity."
      : "no decisive route cues; defaulting to recall and reporting ambiguity.",
    routeAmbiguous: true,
  };
}

export type PipelineCandidate = SelectionCandidate & {
  section: string | null;
  score: number;
  lexicalRank: number | null;
  denseRank: number | null;
};

export type PipelineOptions = {
  query: string;
  route: RouteBlock;
  standpoint: TemporalStandpoint;
  frame: FrameResult;
  trustPolicy: TrustPolicy;
  standing: StandingState;
  requiredLevel: TrustLevel;
  selectionMode: SelectionMode;
  budget: Budget;
};

export type PipelineResult = {
  content: string;
  chars: number;
  admitted: PipelineCandidate[];
  denied: Array<{ candidateId: string; reason: string }>;
  quarantined: Array<{ candidateId: string; reason: string }>;
  trustSummary: { mode: string; level: string; admitted: number; denied: number; quarantined: number };
  selection: ReturnType<typeof selectCandidates>;
  admissionNote: string;
  stageMap: Record<string, { terminalStage: string; stages: Record<string, { admitted: boolean; reason: string }> }>;
};

/**
 * Pure pipeline core: trust -> instruction screen -> selection -> render.
 * Recall admits revoked history with annotation; influence denies it.
 */
export function runPipelineStages(candidates: PipelineCandidate[], options: PipelineOptions): PipelineResult {
  const stageMap: PipelineResult["stageMap"] = {};
  const admitted: PipelineCandidate[] = [];
  const denied: Array<{ candidateId: string; reason: string }> = [];
  const quarantined: Array<{ candidateId: string; reason: string }> = [];

  for (const c of candidates) {
    const stages: Record<string, { admitted: boolean; reason: string }> = {
      retrieved: { admitted: true, reason: "returned by hybrid retrieval." },
      temporal: { admitted: true, reason: `temporal standpoint ${options.standpoint.mode} recorded; no suppression at baseline.` },
      frame: { admitted: true, reason: options.frame.applied ? "frame applied without candidate exclusion." : "no frame applied." },
    };
    const decision = decideTrust(options.trustPolicy, options.standing, c.sourceId, options.requiredLevel);
    const screen = screenInstructions(c.text);
    if (!screen.clean && options.route.route === "influence") {
      stages["trust"] = { admitted: false, reason: `quarantined: instruction-like content (${screen.flags.join(", ")}).` };
      quarantined.push({ candidateId: c.candidateId, reason: stages["trust"].reason });
      stageMap[c.candidateId] = { terminalStage: "quarantined", stages };
      continue;
    }
    if (decision.verdict === "deny" && options.route.route === "influence") {
      stages["trust"] = { admitted: false, reason: decision.reason };
      denied.push({ candidateId: c.candidateId, reason: decision.reason });
      stageMap[c.candidateId] = { terminalStage: "denied", stages };
      continue;
    }
    stages["trust"] = {
      admitted: true,
      reason: options.route.route === "recall" && decision.verdict === "deny"
        ? `recalled despite ${decision.reason} recall preserves history.`
        : decision.reason,
    };
    admitted.push(c);
    stageMap[c.candidateId] = { terminalStage: "admitted", stages };
  }

  const selection = selectCandidates(admitted, options.selectionMode, options.budget);
  const selectedIds = new Set(selection.selected.map((s) => s.candidateId));
  for (const c of admitted) {
    const entry = stageMap[c.candidateId];
    if (!entry) continue;
    if (selectedIds.has(c.candidateId)) {
      entry.stages["selected"] = { admitted: true, reason: "selected within budget." };
      entry.terminalStage = "selected";
    } else {
      const drop = selection.dropped.find((d) => d.candidateId === c.candidateId);
      entry.stages["selected"] = { admitted: false, reason: drop?.reason ?? "not selected." };
      entry.terminalStage = "dropped";
    }
  }

  const parts = selection.selected.map((s) => {
    const full = admitted.find((c) => c.candidateId === s.candidateId);
    return `[source:${s.sourceId} chunk:${s.candidateId}]\n${s.text}`;
    void full;
  });
  const content = parts.join("\n\n---\n\n");
  const admissionNote = options.route.route === "recall"
    ? `recall: ${admitted.length} admitted (history preserved), ${quarantined.length} quarantined from influence only.`
    : `influence: ${selection.selected.length} selected of ${candidates.length} retrieved; ${denied.length} denied, ${quarantined.length} quarantined.`;
  return {
    content,
    chars: content.length,
    admitted,
    denied,
    quarantined,
    trustSummary: {
      mode: options.route.route,
      level: options.requiredLevel,
      admitted: admitted.length,
      denied: denied.length,
      quarantined: quarantined.length,
    },
    selection,
    admissionNote,
    stageMap,
  };
}

