169:       const s = ident(this.options.schema);
170:       for (const [key, value] of [
171:         ["project.path", canonical],
172:         ["project.schema", this.options.schema],
173:         ["project.recorded_at", stamp],
174:       ] as Array<[string, string]>) {
175:         await client.query(
176:           `INSERT INTO ${s}.meta (key, value) VALUES ($1, $2) ON CONFLICT (key) DO NOTHING`,
177:           [key, value],
178:         );
179:       }
180:     } finally {
181:       client.release();
182:     }
183:   }
184: 
185:   async refresh(): Promise<RefreshReport> {
186:     const pool = await this.poolConnected();
187:     const store = this.store(pool);
188:     // Baseline refresh requires an initialised store (mirrors bridge initialise()).
189:     const probe = await this.embedder.embed(["dimension probe"]);
190:     await store.initialise(probe.dimension);
191:     await this.ensureProjectMeta(pool);
192: 
193:     const report: RefreshReport = {
194:       ok: true,
195:       schema: this.options.schema,
196:       discovered: 0,
197:       indexed: 0,
198:       unchanged: 0,
199:       added: 0,
200:       changed: 0,
201:       removed: 0,
202:       chunks: 0,
203:       embedded: 0,
204:       failed: [],
205:     };
206:     const { realpath } = await import("node:fs/promises");
207:     let root: string;
208:     try {
209:       root = await realpath(this.options.projectDirectory);
210:     } catch {
211:       const { resolve } = await import("node:path");
212:       root = resolve(this.options.projectDirectory);
213:     }
214:     const paths = await discover(root);
215:     report.discovered = paths.length;
216:     const known = await store.knownSources();
217:     const seen = new Set<string>();
218:     const version = await this.embeddingVersion();
219:     for (const fullPath of paths) {
220:       const source = await parseFile(fullPath, root);
221:       if (!source) {
222:         const { basename } = await import("node:path");
223:         report.failed.push(basename(fullPath));
224:         continue;
225:       }
226:       seen.add(source.sourceId);
227:       if (known[source.sourceId] === source.contentHash) {
228:         report.unchanged += 1;
229:         continue;
230:       }
231:       const isNew = !(source.sourceId in known);
232:       await store.upsertSource(source.sourceId, source.artifactType, source.contentHash, source.timestamp);
233:       const chunks = chunkSource(source, this.chunking);
234:       const texts = chunks.map((c) => c.text);
235:       const vectors = texts.length ? (await this.embedder.embed(texts)).vectors : [];
236:       const rows = chunks.map((c, i) => ({
237:         chunkId: c.chunkId,
238:         sourceId: c.sourceId,
239:         ordinal: c.ordinal,
240:         text: c.text,
241:         section: c.section,
242:         charStart: c.charStart,
243:         charEnd: c.charEnd,
244:         contentHash: c.contentHash,
245:         chunker: `${this.chunking.policy}:${this.chunking.chunkerVersion}`,
246:         embeddingVersion: version,
247:         embedding: vectors[i] ?? [],
248:       }));
249:       await store.replaceChunks(source.sourceId, rows);
250:       report.chunks += rows.length;
251:       report.embedded += rows.length;
252:       report.indexed += 1;
253:       if (isNew) report.added += 1;
254:       else report.changed += 1;
255:     }
256:     for (const sourceId of Object.keys(known).sort()) {
257:       if (seen.has(sourceId)) continue;
258:       // Explicit-memory sources are managed by the write subsystem,
259:       // not by repository discovery: refresh must never prune them.
260:       if (sourceId.startsWith("memory://")) continue;
261:       await store.removeSource(sourceId);
262:       report.removed += 1;
263:     }
264:     await store.ensureHnsw();
265:     await this.verifyWith(store);
266:     return report;
267:   }
268: 
269:   private async embeddingVersion(): Promise<string> {
270:     // Version without dimension probe side effects: derive from spec.
271:     // The stored per-chunk version is provider:model:dimension after first embed.
272:     const probe = await this.embedder.embed(["dimension probe"]);
273:     return `${probe.provider}:${probe.model}:${probe.dimension}`;
274:   }
275: 
276:   async verify(): Promise<void> {
277:     const pool = await this.poolConnected();
278:     await this.verifyWith(this.store(pool));
279:   }
280: 
281:   private async verifyWith(store: BaselineStore): Promise<void> {
282:     if (await store.orphanChunks()) {
283:       throw new EngineError("VERIFY_FAILED", "orphan chunks remain after refresh");
284:     }
285:     const versions = await store.embeddingVersions();
286:     if (versions.length > 1) {
287:       throw new EngineError(
288:         "VERIFY_FAILED",
289:         `mixed embedding versions in store: ${JSON.stringify(versions.sort())}`,
290:       );
291:     }
292:   }
293: 
294:   async search(query: string, limit = 8): Promise<SearchResult> {
295:     const trimmed = query.trim();
296:     if (!trimmed) {
297:       return { ok: true, indexed: true, schema: this.options.schema, items: [], trace: null, message: "empty query: no retrieval attempted." };
298:     }
299:     const boundedLimit = Math.max(1, Math.min(limit, 20));
300:     const pool = await this.poolConnected();
301:     const client = await pool.connect();
302:     try {
303:       const reg = await client.query("SELECT to_regclass($1)", [`${this.options.schema}.chunks`]);
304:       if (reg.rows[0]?.to_regclass == null) {
305:         return { ok: true, indexed: false, schema: this.options.schema, items: [], trace: null, message: NOT_INDEXED_MESSAGE };
306:       }
307:     } finally {
308:       client.release();
309:     }
310:     const probe = await this.embedder.embed(["dimension probe"]);
311:     const embIdentity = {
312:       provider: probe.provider,
313:       model: probe.model,
314:       dimension: probe.dimension,
315:       version: `${probe.provider}:${probe.model}:${probe.dimension}`,
316:     };
317:     const retriever = new Retriever(this.store(pool), this.embedder, this.options.retrieval);
318:     const trace: RetrievalTrace = await retriever.retrieve(trimmed);
319:     const lexicalRanks = new Map(trace.lexical.map((c) => [c.chunkId, c.rank]));
320:     const denseRanks = new Map(trace.dense.map((c) => [c.chunkId, c.rank]));
321:     const finalStage = this.options.retrieval.reranker !== "none" ? "reranked" : "fused";
322:     const items: SearchItem[] = trace.reranked.slice(0, boundedLimit).map((c) => ({
323:       chunk_id: c.chunkId,
324:       source_id: c.sourceId,
325:       section: c.section,
326:       rank: c.rank,
327:       score: c.score,
328:       text: c.text,
329:       lexical_rank: lexicalRanks.get(c.chunkId) ?? null,
330:       dense_rank: denseRanks.get(c.chunkId) ?? null,
331:       stage: finalStage,
332:     }));
333:     return {
334:       ok: true,
335:       indexed: true,
336:       schema: this.options.schema,
337:       items,
338:       trace: {
339:         query: trace.query,
340:         mode: this.options.retrieval.mode,
341:         lexical_count: trace.lexical.length,
342:         dense_count: trace.dense.length,
343:         fused_count: trace.fused.length,
344:         reranked_count: trace.reranked.length,
345:         lexical_ids: trace.lexical.map((c) => c.chunkId),
346:         dense_ids: trace.dense.map((c) => c.chunkId),
347:         fused_ids: trace.fused.map((c) => c.chunkId),
348:         reranked_ids: trace.reranked.map((c) => c.chunkId),
349:         latencies_ms: Object.fromEntries(
350:           Object.entries(trace.latenciesMs).map(([k, v]) => [k, Math.round(v * 100) / 100]),
351:         ),
352:         embedding: embIdentity,
353:         retrieval: {
354:           mode: this.options.retrieval.mode,
355:           lexical_k: this.options.retrieval.lexicalK,
356:           dense_k: this.options.retrieval.denseK,
357:           fusion_k: this.options.retrieval.fusionK,
358:           rerank_k: this.options.retrieval.rerankK,
359:           reranker: this.options.retrieval.reranker,
360:         },
361:         dense_executed: "dense" in trace.latenciesMs,
362:       },
363:     };
364:   }
