    const { TemporalService: Service } = await import("./temporal/service");
    const summary = await new Service(pgStore).importFile(this.options.projectDirectory);
    return summary;
  } catch {
    return { imported: 0, duplicates: 0, failed: [], events: 0, subjects: [] };
  }
}

