737: export class ProjectMemoryClient {
738:   constructor(
739:     private readonly config: RememberingConfig,
740:     private readonly projectDirectory: string,
741:   ) {}
742: 
743:   get schema(): string {
744:     return this.config.schema;
745:   }
746: 
747:   private call<T>(action: string, payload: Record<string, unknown> = {}): Promise<T> {
748:     const input = JSON.stringify({
749:       ...payload,
750:       schema: this.config.schema,
751:       project_directory: this.projectDirectory,
752:       embedding: {
753:         provider: this.config.embedding.provider,
754:         model: this.config.embedding.model,
755:         host: this.config.embedding.host,
756:       },
757:       retrieval: {
758:         mode: this.config.retrieval.mode,
759:         lexical_k: this.config.retrieval.lexicalK,
760:         dense_k: this.config.retrieval.denseK,
761:         fusion_k: this.config.retrieval.fusionK,
762:         rerank_k: this.config.retrieval.rerankK,
763:         reranker: this.config.retrieval.reranker,
764:       },
765:     });
766: 
767:     return new Promise<T>((resolve, reject) => {
768:       const child = spawn(this.config.python, [this.config.bridgePath, action], {
769:         windowsHide: true,
770:         env: {
771:           ...process.env,
772:           MEMORY_BASELINE_DSN: this.config.dsn,
773:         },
774:         stdio: ["pipe", "pipe", "pipe"],
775:       });
776: 
777:       let stdout = "";
778:       let stderr = "";
779:       const timeout = setTimeout(
780:         () => {
781:           child.kill();
782:           reject(new Error(`Project Memory bridge timed out (${action})`));
783:         },
784:         TIMEOUTS_MS[action] ?? 60_000,
785:       );
786: 
787:       child.stdout.setEncoding("utf8");
788:       child.stderr.setEncoding("utf8");
789:       child.stdout.on("data", (chunk: string) => {
790:         stdout += chunk;
791:       });
792:       child.stderr.on("data", (chunk: string) => {
793:         stderr += chunk;
794:       });
795: 
796:       child.on("error", (error) => {
797:         clearTimeout(timeout);
798:         reject(
799:           new Error(
800:             `Project Memory bridge failed to start (${action}): ${error.message}`,
801:             { cause: error },
802:           ),
803:         );
804:       });
805: 
806:       child.on("close", (code) => {
807:         clearTimeout(timeout);
808:         if (code !== 0) {
809:           reject(
810:             new Error(
811:               `Project Memory bridge failed (${action}, exit=${code}): ${stderr.trim() || stdout.trim()}`,
812:             ),
813:           );
814:           return;
815:         }
816: 
817:         if (stderr.trim()) {
818:           console.warn(`[opencode-remembering] bridge stderr: ${stderr.trim()}`);
819:         }
820: 
821:         try {
822:           resolve(JSON.parse(stdout) as T);
823:         } catch (error) {
824:           reject(
825:             new Error(
826:               `Project Memory bridge returned invalid JSON (${action}): ${stdout.slice(0, 500)}`,
827:               { cause: error },
828:             ),
829:           );
830:         }
831:       });
832: 
833:       child.stdin.end(input);
834:     });
835:   }
